49	const componentGroupBase = (count: number): number =>
50	  count === COMPONENT_BLOCK_SIZE
51	    ? COMPONENT_BLOCK_PREMIUM
52	    : count * COMPONENT_BASE_PREMIUM;
53	
54	const countByType = (items: Item[]): Map<string, number> => {
55	  const counts = new Map<string, number>();
56	  for (const item of items) {
57	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
58	  }
59	  return counts;
60	};
61	
62	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
63	
64	const isHighEnchantment = (item: Item): boolean =>
65	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
66	
67	interface PricedUnit {
68	  base: number;
69	  surcharges: number[];
70	}
71	
72	const mainItemUnit = (item: Item): PricedUnit => {
73	  const base = BASE_PREMIUMS[item.type];
74	  const surcharges: number[] = [];
75	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
76	  if (isHighEnchantment(item)) surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
77	  return { base, surcharges };
78	};
79	
80	const componentUnit = (count: number): PricedUnit => ({
81	  base: componentGroupBase(count),
82	  surcharges: [],
83	});
84	
85	const pricedUnits = (items: Item[]): PricedUnit[] => {
86	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
87	
88	  const components = items.filter(isComponent);
89	  const componentUnits = [...countByType(components).values()].map(componentUnit);
90	
91	  return [...mainUnits, ...componentUnits];
92	};
93	
94	const unitTotal = (unit: PricedUnit): number =>
95	  unit.base +
96	  unit.base * FIRST_INSURANCE_SURCHARGE +
97	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
98	
99	// Policy-level discount fractions applied to the policy base (sum of unit bases).
100	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
101	// contract discount) can be added here without touching per-item pricing.
102	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
103	  const fractions: number[] = [];
104	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
105	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
106	  return fractions;
107	};
108	
109	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
110	  const units = pricedUnits(items);
111	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
112	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
113	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
114	    (sum, fraction) => sum + policyBase * fraction,
115	    0,
116	  );
117	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
118	};
119	
120	export const runScenario = (scenario: Scenario): ScenarioResult => {
121	  let quoteCount = 0;
122	  const results = scenario.steps.map((step) => {
123	    const isFollowUp = quoteCount > 0;
124	    quoteCount += 1;
125	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
126	  });
127	  return { results };
128	};
